import { GoogleGenAI } from '@google/genai';

const SYSTEM_PROMPT = `You are an elite Principal Software Engineer and System Architect. Your job is to take a developer's rough app idea and generate a dense, token-optimized architectural master specification.
Apply industry best practices automatically. Be structured, precise, and high-signal. Do not include introductory text or conversational fluff.`;

export async function POST(req) {
  try {
    const { appName, features, techStack, designVibe, advancedConstraints, customApiKey, outputFormat, enableRedTeam } = await req.json();

    // Use custom BYOK key if provided, otherwise fall back to shared .env.local key
    const apiKey = customApiKey || process.env.GOOGLE_API_KEY;
    if (!apiKey) {
      return Response.json({ error: "No API key found. Please check your settings." }, { status: 401 });
    }

    const ai = new GoogleGenAI({ apiKey });

    // Dynamic Format Routing
    let formatInstruction = "";
    if (outputFormat === 'cursorrules') {
      formatInstruction = `\nCRITICAL FORMATTING RULE: Output this specification strictly in the format of a ".cursorrules" or "CLAUDE.md" AI IDE configuration file. Use imperative rules, clear markdown headers, and explicit project boundaries that an AI coding agent (like Cursor or Windsurf) can read directly to generate code without making assumptions.`;
    } else {
      formatInstruction = `\nCRITICAL FORMATTING RULE: Format the output as a structured Markdown architectural blueprint ready to be pasted into an LLM chat prompt.`;
    }

    // Dynamic Red-Team Stress Test
    let redTeamInstruction = "";
    if (enableRedTeam) {
      redTeamInstruction = `\nMANDATORY RED-TEAM STRESS TEST: At the very bottom of your output, add a section called "⚠️ Principal Engineer Red-Team Warning:". In this section, ruthlessly roast/stress-test the architecture. Identify the #1 technical bottleneck, security flaw, or scalability pitfall this MVP will face under load, and explain exactly how to engineer around it before writing line one of code.`;
    }

    const userContent = `
      Create a master architectural coding specification for the following application:
      - App Name & Identity: ${appName || 'Not specified'}
      - Core MVP Features & Superpowers: ${features || 'Not specified'}
      - Tech Stack Architecture: ${techStack || 'Not specified'}
      - UI/UX Design System: ${designVibe || 'Not specified'}
      ${advancedConstraints ? `- STRICT ARCHITECTURAL CONSTRAINTS & RULES: ${advancedConstraints}` : ''}
      ${formatInstruction}
      ${redTeamInstruction}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3.5-flash',
      contents: userContent,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        temperature: 0.3,
      }
    });

    return Response.json({ result: response.text });
  } catch (error) {
    return Response.json({ error: error.message || "Compilation failed." }, { status: 500 });
  }
}